758  int pn_message_decode(pn_message_t *msg, const char *bytes, size_t size)
   759  {
   760    assert(msg && bytes && size);
   761
   762    pn_bytes_t msg_bytes = {.size=size, .start=bytes};
   763    while (msg_bytes.size) {
   764      bool scanned;
   765      uint64_t desc;
   766      size_t section_size = pn_amqp_decode_DQLq(msg_bytes, &scanned, &desc);
   767      if (!scanned) {
   768        desc = 0;
   769      }
   770
   771      switch (desc) {
   772        case HEADER: {
   773          bool priority_q;
   774          uint8_t priority;
   775          pn_amqp_decode_DqEoQBIoIe(msg_bytes,
   776                                    &msg->durable,
   777                                    &priority_q, &priority,
   778                                    &msg->ttl,
   779                                    &msg->first_acquirer,
   780                                    &msg->delivery_count);
   781          msg->priority = priority_q ? priority : HEADER_PRIORITY_DEFAULT;
   782          break;
   783        }
   784        case PROPERTIES: {
   785          pn_bytes_t user_id, address, subject, reply_to, ctype, cencoding,
   786                     group_id, reply_to_group_id;
   787          pn_atom_t id;
   788          pn_atom_t correlation_id;
   789          pn_amqp_decode_DqEazSSSassttSISe(msg_bytes,  &id,
   790                             &user_id, &address, &subject, &reply_to,
   791                             &correlation_id, &ctype, &cencoding,
   792                             &msg->expiry_time, &msg->creation_time, &group_id,
   793                             &msg->group_sequence, &reply_to_group_id);
   794          pni_msgid_fix_interop(&id);
   795          pn_message_set_id(msg, id);
   796          int err = pn_string_set_bytes(msg->user_id, user_id);
   797          if (err) return pn_error_format(msg->error, err, "error setting user_id");
   798          err = pn_string_setn(msg->address, address.start, address.size);
   799          if (err) return pn_error_format(msg->error, err, "error setting address");
   800          err = pn_string_setn(msg->subject, subject.start, subject.size);
   801          if (err) return pn_error_format(msg->error, err, "error setting subject");
   802          err = pn_string_setn(msg->reply_to, reply_to.start, reply_to.size);
   803          if (err) return pn_error_format(msg->error, err, "error setting reply_to");
   804          pni_msgid_fix_interop(&correlation_id);
   805          pn_message_set_correlation_id(msg, correlation_id);
   806          err = pn_string_setn(msg->content_type, ctype.start, ctype.size);
   807          if (err) return pn_error_format(msg->error, err, "error setting content_type");
   808          err = pn_string_setn(msg->content_encoding, cencoding.start,
   809                               cencoding.size);
   810          if (err) return pn_error_format(msg->error, err, "error setting content_encoding");
   811          err = pn_string_setn(msg->group_id, group_id.start, group_id.size);
   812          if (err) return pn_error_format(msg->error, err, "error setting group_id");
   813          err = pn_string_setn(msg->reply_to_group_id, reply_to_group_id.start,
   814                               reply_to_group_id.size);
   815          if (err) return pn_error_format(msg->error, err, "error setting reply_to_group_id");
   816          break;
   817        }
   818        case DELIVERY_ANNOTATIONS: {
   819          pn_data_clear(msg->instructions);
   820          pn_amqp_decode_DqC(msg_bytes, msg->instructions);
   821          pn_data_rewind(msg->instructions);
   822          break;
   823        }
   824        case MESSAGE_ANNOTATIONS: {
   825          pn_data_clear(msg->annotations);
   826          pn_amqp_decode_DqC(msg_bytes, msg->annotations);
   827          pn_data_rewind(msg->annotations);
   828          break;
   829        }
   830        case APPLICATION_PROPERTIES: {
   831          pn_data_clear(msg->properties);
   832          pn_amqp_decode_DqC(msg_bytes, msg->properties);
   833          pn_data_rewind(msg->properties);
   834          break;
   835        }
   836        case DATA:
   837        case AMQP_SEQUENCE: {
   838          msg->inferred = true;
   839          pn_data_clear(msg->body);
   840          pn_amqp_decode_DqC(msg_bytes, msg->body);
   841          pn_data_rewind(msg->body);
   842          break;
   843        }
   844        case AMQP_VALUE: {
   845          msg->inferred = false;
   846          pn_data_clear(msg->body);
   847          pn_amqp_decode_DqC(msg_bytes, msg->body);
   848          pn_data_rewind(msg->body);
   849          break;
   850        }
   851        case FOOTER:
   852          break;
   853        default: {
   854          pn_data_clear(msg->body);
   855          pn_data_decode(msg->body, msg_bytes.start, msg_bytes.size);
   856          pn_data_rewind(msg->body);
   857          break;
   858        }
   859      }
   860      msg_bytes = (pn_bytes_t){.size=msg_bytes.size-section_size, .start=msg_bytes.start+section_size};
   861    }
   862    return 0;
   863  }
